41	
42	export interface DuelMachineOptions {
43	  readonly lobby: DuelLobbySchema;
44	  readonly seed: number;
45	  readonly send: DuelSend;
46	  /**
47	   * How the fight starts. `countdown` (the standalone duel): when the countdown ends. `called` (a duel at sea): when
48	   * the host calls `start()`, which the encounter rules decide (§6: the countdown is over and both fighters are
49	   * ready); a countdown that ends first waits in `waiting`, with no probes.
50	   */
51	  readonly start: "countdown" | "called";
52	  readonly config?: DuelConfig;
53	}
54	
55	interface Seat {
56	  readonly slot: PlayerIndex;
57	  readonly gate: DuelInputGate;
58	  readonly schema: DuelSeatSchema;
59	  /** Probe ids in flight and when they were sent (performance.now()). */
60	  readonly probes: Map<number, number>;
61	  readonly rtts: number[];
62	  nextProbe: number;
63	  /** At sea: the fighter reported its arena loaded. */
64	  ready: boolean;
65	}
66	
67	/** What a duel reports to tests and diagnostics, running or finished. */
68	export interface DuelDiagnostics {
69	  readonly phase: DuelRoomPhase;
70	  readonly frame: number;
71	  readonly inputDelay: number;
72	  readonly authority: AuthorityStats;
73	  /** Input messages the gate dropped, per slot and reason. */
74	  readonly dropped: Record<string, DuelInputGate["dropped"]>;
75	  readonly rttSamples: Record<string, readonly number[]>;
76	}
77	
78	/** How a duel ended: the winner's slot (null for none) and why, on which frame. */
79	export interface DuelOutcome {
80	  readonly winner: PlayerIndex | null;
81	  readonly reason: DuelEndReason;
82	  readonly frame: number;
83	}
84	
85	/**
86	 * One 1v1 duel's machine (§15), the same for a standalone duel room and a duel inside a match room, so the two
87	 * cannot drift: seats and their input gates, the three-second countdown with round-trip probes and the shared input
88	 * delay chosen DELAY_DECISION_FRAMES before its end, then `DuelAuthority` stepped once per `advance` (60 Hz) with a
89	 * frame bundle every third frame. It keeps the reconnection bookkeeping (a dropped seat is marked away and gets a
90	 * snapshot bundle when it is back) and the forfeits (a seat that left for good during the countdown or the fight),
91	 * decided together at the next frame boundary, so the order two leaves are processed in never picks a winner (§12).
92	 * The host room owns the clients and the timer: it calls these methods from its handlers and its fixed step.
93	 */
94	export class DuelMachine {
95	  readonly authority: DuelAuthority;
96	  private readonly config: DuelConfig;
97	  private readonly lobby: DuelLobbySchema;
98	  private readonly send: DuelSend;
99	  private readonly startWhen: DuelMachineOptions["start"];
100	  private readonly seats = new Map<string, Seat>();
101	  /** Players who left for good (quit, or absent past the reconnection window) since the last frame boundary. */
102	  private readonly forfeits = new Set<PlayerIndex>();
103	  /** Room ticks (one per `advance`), the input gates' rate window. */
104	  private tick = 0;
105	  private startCalled = false;
106	  private ended: DuelOutcome | undefined;
107	
108	  constructor(options: DuelMachineOptions) {
109	    this.config = options.config ?? defaultDuelConfig;
110	    this.lobby = options.lobby;
111	    this.send = options.send;
112	    this.startWhen = options.start;
113	    this.authority = new DuelAuthority(this.config, createDuelState(this.config, { seed: options.seed }));
114	    this.lobby.phase = "waiting";
115	    this.lobby.countdown = DUEL_COUNTDOWN_FRAMES;
116	    this.lobby.seed = options.seed;
117	    this.lobby.winner = -1;
118	  }
119	
120	  get phase(): DuelRoomPhase {
121	    return this.lobby.phase as DuelRoomPhase;
122	  }
123	
124	  /** The result once the duel is over. */
125	  get outcome(): DuelOutcome | undefined {
126	    return this.ended;
127	  }
128	
129	  /** The authoritative duel state. */
130	  get state(): DuelState {
131	    return this.authority.state;
132	  }
133	
134	  /** The seat's slot, if the session holds one. */
135	  slotOf(sessionId: string): PlayerIndex | undefined {
136	    return this.seats.get(sessionId)?.slot;
137	  }
138	
139	  /** The session holding a slot. */
140	  sessionOf(slot: PlayerIndex): string | undefined {
141	    return [...this.seats.entries()].find(([, seat]) => seat.slot === slot)?.[0];
142	  }
143	
144	  /** Whether the seat's fighter reported ready (at sea). */
145	  isReady(sessionId: string): boolean {
146	    return this.seats.get(sessionId)?.ready === true;
147	  }
148	
149	  /** Seats a player; the lobby lists the seat. */
150	  addSeat(sessionId: string, slot: PlayerIndex): void {
151	    const schema = new DuelSeatSchema();
152	    schema.sessionId = sessionId;
153	    schema.slot = slot;
154	    schema.connected = true;
155	    this.lobby.seats.push(schema);
156	    this.seats.set(sessionId, { slot, gate: new DuelInputGate(), schema, probes: new Map(), rtts: [], nextProbe: 1, ready: false });
157	  }
158	
159	  /** Frees a seat before the countdown (a standalone duel's player who left while waiting). */
160	  removeSeat(sessionId: string): void {
161	    this.seats.delete(sessionId);
162	    const index = this.lobby.seats.findIndex((entry) => entry.sessionId === sessionId);
163	    if (index >= 0) this.lobby.seats.splice(index, 1);
164	  }
165	
166	  /** Starts the three-second countdown. */
167	  beginCountdown(): void {
168	    if (this.phase === "waiting" && this.lobby.countdown === DUEL_COUNTDOWN_FRAMES) this.lobby.phase = "countdown";
169	  }
170	
171	  /** At sea: the encounter rules started the fight. It begins when the countdown is over (at once if it is). */
172	  start(): void {
173	    if (this.startWhen !== "called" || this.ended !== undefined) return;
174	    this.startCalled = true;
175	    if (this.phase === "waiting" && this.lobby.countdown === 0) this.beginFight();
176	  }
177	
178	  /** Makes a player's input come from a script (the practice dummy). */
179	  script(player: PlayerIndex, script: ((state: DuelState) => number) | undefined): void {
180	    this.authority.script(player, script);
181	  }
182	
183	  /** A fighter's arena is loaded (at sea). */
184	  markReady(sessionId: string): void {
185	    const seat = this.seats.get(sessionId);
186	    if (seat !== undefined) seat.ready = true;
187	  }
188	
189	  /** The duel's frame on one timeline: negative during the countdown, then the frames stepped. */
190	  get serverFrame(): number {
191	    return this.phase === "countdown" || this.phase === "waiting" ? 0 - this.lobby.countdown : this.authority.frame;
192	  }
193	
194	  /** One untrusted input message from a seat; `acceptFrom` refuses a slot whose input is scripted. */
195	  receiveInput(sessionId: string, message: unknown, acceptFrom: (slot: PlayerIndex) => boolean = () => true): void {
196	    const seat = this.seats.get(sessionId);
197	    if (seat === undefined || (this.phase !== "countdown" && this.phase !== "fighting")) return;
198	    const input = seat.gate.receive(message, this.tick, this.serverFrame);
199	    if (input === undefined || !acceptFrom(seat.slot)) return;
200	    this.authority.receive(seat.slot, input.frame, input.inputs);
201	  }
202	
203	  /** One untrusted probe echo from a seat. */
204	  receiveProbeReply(sessionId: string, message: unknown): void {
205	    const seat = this.seats.get(sessionId);
206	    const reply = duelProbeReplySchema.safeParse(message);
207	    if (seat === undefined || !reply.success) return;
208	    const sentAt = seat.probes.get(reply.data.id);
209	    if (sentAt === undefined) return;
210	    seat.probes.delete(reply.data.id);
211	    seat.rtts.push(performance.now() - sentAt);
212	    if (seat.rtts.length > PROBE_SAMPLES) seat.rtts.shift();
213	    seat.schema.rtt = Math.round(linkStats(seat.rtts)!.rttMs);
214	  }
215	
216	  /** A seat's connection dropped (the host keeps it for DUEL_RECONNECT_SECONDS). */
217	  drop(sessionId: string): void {
218	    const seat = this.seats.get(sessionId);
219	    if (seat === undefined || this.phase === "over") return;
220	    seat.schema.connected = false;
221	    seat.probes.clear();
222	  }
223	
224	  /** The same player is back: they continue from the authoritative state, which a snapshot bundle gives them. */
225	  reconnect(sessionId: string): void {
226	    const seat = this.seats.get(sessionId);
227	    if (seat === undefined) return;
228	    seat.schema.connected = true;
229	    if (this.phase === "fighting" || this.phase === "over") this.send(sessionId, DuelMessageType.Frames, this.authority.snapshotBundle());
230	  }
231	
232	  /**
233	   * A seat left for good (quit, or absent past the reconnection window). Once the countdown has begun that forfeits,
234	   * decided at the next frame boundary together with any other forfeit on that frame.
235	   */
236	  leave(sessionId: string): void {
237	    const seat = this.seats.get(sessionId);
238	    if (seat === undefined) return;
239	    seat.schema.connected = false;
240	    if (this.phase === "countdown" || this.phase === "fighting" || (this.phase === "waiting" && this.lobby.countdown < DUEL_COUNTDOWN_FRAMES)) {
241	      this.forfeits.add(seat.slot);
242	    }
243	  }
244	
245	  /** Ends the duel from outside (at sea, the encounter rules' ready check: one forfeit, or a cancellation). */
246	  end(winner: PlayerIndex | null, reason: DuelEndReason): void {
247	    this.finish(winner, reason, Math.max(0, this.authority.frame));
248	  }
249	
250	  /** One 60 Hz frame: forfeits, then the countdown or the fight. */
251	  advance(): void {
252	    this.tick++;
253	    if (this.resolveForfeits()) return;
254	    switch (this.phase) {
255	      case "countdown":
256	        this.lobby.countdown--;
257	        if (this.lobby.countdown % COUNTDOWN_PROBE_FRAMES === 0) this.sendProbes();
258	        if (this.lobby.countdown === DELAY_DECISION_FRAMES) {
259	          this.lobby.inputDelay = inputDelayFromSamples([...this.seats.values()].map((seat) => seat.rtts));
260	        }
261	        if (this.lobby.countdown === 0) {
262	          if (this.startWhen === "countdown" || this.startCalled) this.beginFight();
263	          else this.lobby.phase = "waiting";
264	        }
265	        return;
266	      case "fighting": {
267	        const bundle = this.authority.step();
268	        if (bundle !== undefined) this.broadcast(bundle);
269	        if (this.authority.frame % FIGHT_PROBE_FRAMES === 0) this.sendProbes();
270	        const result = this.authority.state.result;
271	        if (result !== null) this.finish(result.winner, result.reason, result.frame);
272	        return;
273	      }
274	      default:
275	        return;
276	    }
277	  }
278	
279	  /** The duel's counters, for tests and the harness. */
280	  diagnostics(): DuelDiagnostics {
281	    const bySlot = <T>(pick: (seat: Seat) => T) => Object.fromEntries([...this.seats.values()].map((seat) => [String(seat.slot), pick(seat)]));
282	    return {
283	      phase: this.phase,
284	      frame: this.authority.frame,
285	      inputDelay: this.lobby.inputDelay,
286	      authority: structuredClone(this.authority.stats),
287	      dropped: bySlot((seat) => ({ ...seat.gate.dropped })),
288	      rttSamples: bySlot((seat) => [...seat.rtts]),
289	    };
290	  }
291	
292	  /** Inputs dropped for a seat, by reason. */
293	  droppedInputs(sessionId: string): DuelInputGate["dropped"] | undefined {
294	    return this.seats.get(sessionId)?.gate.dropped;
295	  }
296	
297	  private beginFight(): void {
298	    this.lobby.phase = "fighting";
299	    this.broadcast(this.authority.snapshotBundle());
300	  }
301	
302	  private broadcast(bundle: AuthorityBundle): void {
303	    for (const sessionId of this.seats.keys()) this.send(sessionId, DuelMessageType.Frames, bundle);
304	  }
305	
306	  private sendProbes(): void {
307	    for (const [sessionId, seat] of this.seats) {
308	      if (!seat.schema.connected) continue;
309	      const id = seat.nextProbe++;
310	      seat.probes.set(id, performance.now());
311	      // Probes that never came back (a dropped connection) are forgotten after a few seconds' worth.
312	      for (const old of seat.probes.keys()) if (old < id - 20) seat.probes.delete(old);
313	      const probe: DuelProbe = { id, frame: this.serverFrame, rtt: seat.rtts.length === 0 ? 0 : linkStats(seat.rtts)!.rttMs };
314	      this.send(sessionId, DuelMessageType.Probe, probe);
315	    }
316	  }
317	
318	  /**
319	   * §12 at a frame boundary: one player who forfeited since the last frame loses to the other (connected or still
320	   * inside their own window); both forfeiting on the same frame is a result with no winner, so there is nothing to
321	   * award. True when the duel ended here.
322	   */
323	  private resolveForfeits(): boolean {
324	    if (this.forfeits.size === 0) return false;
325	    const [first] = this.forfeits;
326	    const winner: PlayerIndex | null = this.forfeits.size > 1 ? null : first === 0 ? 1 : 0;
327	    this.forfeits.clear();
328	    if (this.phase === "over") return false;
329	    this.finish(winner, "forfeit", Math.max(0, this.authority.frame));
330	    return true;
331	  }
332	
333	  /** Ends the duel: the step's result, a forfeit or a cancellation. Both players see it in the lobby. */
334	  private finish(winner: PlayerIndex | null, reason: DuelEndReason, frame: number): void {
335	    if (this.ended !== undefined) return;
336	    this.ended = { winner, reason, frame };
337	    this.lobby.phase = "over";
338	    this.lobby.winner = winner ?? -1;
339	    this.lobby.reason = reason;
340	    this.lobby.resultFrame = frame;
341	  }
342	}
