252	
253	/** One world tick's snapshot; order within the lists never matters. */
254	export interface EncounterTickInput {
255	  /** Must be the state's tick plus one. */
256	  readonly tick: number;
257	  /** Every player in the match; a player absent from the list is not in it and can neither attack nor be attacked. */
258	  readonly players: readonly EncounterPlayerInput[];
259	  readonly reports: readonly DuelReport[];
