261	  readonly matchOver: boolean;
262	}
263	
264	export type MissReason = "defender-ineligible" | "out-of-range" | "out-of-aim" | "no-line-of-sight";
265	export type ProtectionEndReason = "expired" | "attack" | "claim" | "collection";
266	export type ReportRefusal = "unknown-duel" | "already-ended" | "not-ended" | "invalid";
267	
268	/** Something that happened on a tick, for the caller to apply or announce. */
269	export type EncounterEvent =
270	  | { readonly kind: "protection-ended"; readonly tick: number; readonly playerId: string; readonly reason: ProtectionEndReason }
271	  | { readonly kind: "report-refused"; readonly tick: number; readonly duelId: string; readonly report: "end" | "settled"; readonly reason: ReportRefusal }
272	  /** The caller's end report was accepted. */
273	  | { readonly kind: "duel-ended"; readonly tick: number; readonly duelId: string; readonly outcome: DuelOutcome; readonly winner: string | null; readonly endTick: number }
274	  /** The ledger settled the duel: it no longer counts, and its players return (the events that follow). */
275	  | { readonly kind: "duel-settled"; readonly tick: number; readonly duelId: string }
276	  /** Put the player at this point with this protection: the winner, or both players of a draw or cancellation. */
277	  | { readonly kind: "player-returned"; readonly tick: number; readonly duelId: string; readonly playerId: string; readonly x: number; readonly y: number; readonly protection: Protection }
278	  /** The loser waits out of the world until `respawnTick`. */
279	  | { readonly kind: "player-respawning"; readonly tick: number; readonly duelId: string; readonly playerId: string; readonly respawnTick: number }
280	  | { readonly kind: "player-respawned"; readonly tick: number; readonly playerId: string; readonly x: number; readonly y: number; readonly dockId: number | null; readonly protection: Protection }
281	  | { readonly kind: "duel-started"; readonly tick: number; readonly duelId: string }
282	  /** One client was not ready in time: hand it to the ledger as a win for the other. */
283	  | { readonly kind: "duel-forfeited"; readonly tick: number; readonly duelId: string; readonly forfeiter: string; readonly winner: string }
284	  /** Neither client was ready in time (§12's same-tick double forfeit): hand it to the ledger as cancelled. */
285	  | { readonly kind: "duel-cancelled"; readonly tick: number; readonly duelId: string }
286	  | { readonly kind: "attempt-cancelled"; readonly tick: number; readonly attackerId: string; readonly defenderId: string; readonly reason: "attacker-ineligible" | "match-over" }
287	  | { readonly kind: "attempt-missed"; readonly tick: number; readonly attackerId: string; readonly defenderId: string; readonly reason: MissReason; readonly cooldownEndTick: number }
288	  /** A hit that lost a same-tick conflict, or found the duel cap reached: no cooldown. */
289	  | { readonly kind: "attempt-preempted"; readonly tick: number; readonly attackerId: string; readonly defenderId: string; readonly reason: "conflict" | "duel-cap" }
290	  /** Both players are reserved: hand it to the ledger's `reserveDuel`. */
291	  | { readonly kind: "duel-reserved"; readonly tick: number; readonly duelId: string; readonly mode: EncounterMode; readonly players: readonly [string, string]; readonly x: number; readonly y: number }
292	  | { readonly kind: "attempt-started"; readonly tick: number; readonly attackerId: string; readonly defenderId: string; readonly mode: EncounterMode; readonly aim: number; readonly landTick: number };
293	
294	export type EncounterEventKind = EncounterEvent["kind"];
295	
296	/** Every event kind. */
297	export const ENCOUNTER_EVENT_KINDS: readonly EncounterEventKind[] = [
298	  "protection-ended",
299	  "report-refused",
300	  "duel-ended",
301	  "duel-settled",
302	  "player-returned",
303	  "player-respawning",
304	  "player-respawned",
305	  "duel-started",
306	  "duel-forfeited",
307	  "duel-cancelled",
308	  "attempt-cancelled",
309	  "attempt-missed",
310	  "attempt-preempted",
311	  "duel-reserved",
312	  "attempt-started",
313	];
314	
315	export interface EncounterStepResult {
316	  readonly state: EncounterState;
317	  readonly events: readonly EncounterEvent[];
318	}
319

