422	    const { host, guest } = await pairInRange(endpoint, track, { clients: [{ autoReady: false }, { autoReady: false }] });
423	    await grapple(host, guest);
424	    await host.waitFor(() => host.fighter.phase === "over", 13_000);
425	    expect(lobbyOf(host)).toEqual({ phase: "over", winner: -1, reason: "cancelled" });
426	    for (const client of [host, guest]) await client.waitFor(() => client.status()?.protection === "draw", 2000);
427	  }, 30_000);
