1	import { isNavigable, type SeaMapDefinition } from "@pirate-sea-race/content";
2	import { distanceSquared, seaLineOfSight, tileCentre, tileOf, type EncounterPoint } from "./geometry.js";
3	
4	/** Where a draw or cancellation returns its two players, in the duel's player order. */
5	export interface SeparateReturnRequest {
6	  /** The encounter position: between the two players where the hit landed. */
7	  readonly encounter: EncounterPoint;
8	  /** Each player's own position when the hit landed. */
9	  readonly players: readonly [EncounterPoint, EncounterPoint];
10	  /** Sub-units: the two points are at least this far apart... */
11	  readonly minSeparation: number;
12	  /** ...and each is within this far of the encounter position. */
13	  readonly maxDistance: number;
14	}
15	
16	export interface RespawnRequest {
17	  readonly encounter: EncounterPoint;
18	  /** The loser's own position when the hit landed. */
19	  readonly own: EncounterPoint;
20	  /** Every other active player's position (§6: away from nearby opponents). */
21	  readonly opponents: readonly EncounterPoint[];
22	  /** Sub-units: a dock is clear when no opponent is this close to it. */
23	  readonly clearRadius: number;
24	}
25	
26	export interface RespawnPoint {
27	  readonly x: number;
28	  readonly y: number;
29	  /** The dock the loser respawns at, or null where the mode has no docks. */
30	  readonly dockId: number | null;
31	}
32	
33	/**
34	 * What differs between the sea and the islands: line of sight and where a duel's players return. Each is a pure
35	 * function of its arguments; the step calls it with the duel's mode.
36	 */
37	export interface ModeRules {
38	  lineOfSight(from: EncounterPoint, to: EncounterPoint): boolean;
39	  separateReturn(request: SeparateReturnRequest): readonly [EncounterPoint, EncounterPoint];
40	  respawnPoint(request: RespawnRequest): RespawnPoint;
41	}
42	
43	/**
44	 * The sea (§6 at sea), fully specified:
45	 * - line of sight: the supercover line between the ships' tiles touches no land;
46	 * - a draw returns both ships to the centres of two distinct navigable tiles within `maxDistance` of the encounter
47	 *   and at least `minSeparation` apart, the pair nearest (by the sum of squared distances) to where each ship was,
48	 *   ties to the lower first tile then the lower second tile, row-major; a sea with no such pair leaves each ship
49	 *   where it was;
50	 * - a loser respawns at the centre of the dock nearest the encounter with no opponent within `clearRadius`, ties to
51	 *   the lower dock id; if every dock has one, the dock farthest from its nearest opponent, ties to the lower id.
52	 */
53	export function seaModeRules(map: SeaMapDefinition): ModeRules {
54	  if (map.docks.length === 0) throw new RangeError(`${map.name} has no dock to respawn at`);
55	  const docks = map.docks.map((dock) => ({ id: dock.id, point: tileCentre(map, dock) }));
56	  return {
57	    lineOfSight: (from, to) => seaLineOfSight(map, from, to),
58	
59	    separateReturn({ encounter, players, minSeparation, maxDistance }) {
60	      const reach = Math.ceil(maxDistance / map.subUnitsPerTile) + 1;
61	      const centre = tileOf(map, encounter);
62	      const candidates: EncounterPoint[] = [];
63	      for (let tileY = centre.tileY - reach; tileY <= centre.tileY + reach; tileY++) {
64	        for (let tileX = centre.tileX - reach; tileX <= centre.tileX + reach; tileX++) {
65	          if (!isNavigable(map, tileX, tileY)) continue;
66	          const point = tileCentre(map, { tileX, tileY });
67	          if (distanceSquared(encounter, point) <= maxDistance * maxDistance) candidates.push(point);
68	        }
69	      }
70	      const [a, b] = players;
71	      const toA = candidates.map((point) => distanceSquared(a, point));
72	      const toB = candidates.map((point) => distanceSquared(b, point));
73	      let best: { cost: number; p: number; q: number } | null = null;
74	      for (let p = 0; p < candidates.length; p++) {
75	        for (let q = 0; q < candidates.length; q++) {
76	          if (p === q || distanceSquared(candidates[p]!, candidates[q]!) < minSeparation * minSeparation) continue;
77	          const cost = toA[p]! + toB[q]!;
78	          // Strictly less keeps the first pair in (p, q) order among equals.
79	          if (best === null || cost < best.cost) best = { cost, p, q };
80	        }
81	      }
82	      if (best === null) return [{ x: a.x, y: a.y }, { x: b.x, y: b.y }];
83	      return [candidates[best.p]!, candidates[best.q]!];
84	    },
85	
86	    respawnPoint({ encounter, opponents, clearRadius }) {
87	      const nearestOpponent = (point: EncounterPoint) =>
88	        opponents.reduce((nearest, opponent) => Math.min(nearest, distanceSquared(point, opponent)), Number.MAX_SAFE_INTEGER);
89	      let chosen: { id: number; point: EncounterPoint; key: number } | null = null;
90	      for (const dock of docks) {
91	        if (nearestOpponent(dock.point) <= clearRadius * clearRadius) continue;
92	        const key = distanceSquared(encounter, dock.point);
93	        if (chosen === null || key < chosen.key) chosen = { ...dock, key };
94	      }
95	      if (chosen === null) {
96	        for (const dock of docks) {
97	          const key = nearestOpponent(dock.point);
98	          if (chosen === null || key > chosen.key) chosen = { ...dock, key };
99	        }
100	      }
101	      const { id, point } = chosen!;
102	      return { x: point.x, y: point.y, dockId: id };
103	    },
104	  };
105	}
106	
107	/**
108	 * The islands, as a placeholder until walking on islands exists (`objectives-endgame` replaces it): nothing blocks
109	 * line of sight, and every return stays at the player's own position.
110	 */
111	export const footPlaceholderRules: ModeRules = {
112	  lineOfSight: () => true,
113	  separateReturn: ({ players: [a, b] }) => [
114	    { x: a.x, y: a.y },
115	    { x: b.x, y: b.y },
116	  ],
117	  respawnPoint: ({ own }) => ({ x: own.x, y: own.y, dockId: null }),
118	};
