1	import {
2	  duelFrameBundleSchema,
3	  DuelMessageType,
4	  duelProbeSchema,
5	  type DuelPracticeMessage,
6	  type DuelProbeReply,
7	  type DuelRoomPhase,
8	  type DummyBehaviour,
9	} from "@pirate-sea-race/protocol";
10	import { createDuelState, defaultDuelConfig, type DuelState, type PlayerIndex } from "@pirate-sea-race/simulation/duel";
11	import { DuelClientSession, type DuelFeedEvent } from "@pirate-sea-race/simulation/netcode";
12	import type { ArenaSource } from "./arenaScene.js";
13	import { PendingDuelEvents } from "./duelEvents.js";
14	import { renderDuelHud, resultText, type DuelConnectionStatus } from "./duelHud.js";
15	import { DuelKeyboard } from "./duelKeyboard.js";
16	import type { DuelLobby, DuelTransport } from "./duelTransport.js";
17	
18	/** The client ticks this often: far finer than a frame, and independent of the display's refresh rate. */
19	const TICK_MS = 4;
20	/** The HUD is redrawn this often. */
21	const HUD_MS = 50;
22	
23	const { rules } = defaultDuelConfig.moveset;
24	
25	/**
26	 * One browser's duel, over a standalone duel room or inside a match room (the `DuelTransport` seam): the duel's
27	 * messages feed a `DuelClientSession` (the same rollback core the headless test client runs), a 4 ms timer ticks it
28	 * with the keyboard's input and sends what it returns, the arena draws the predicted state, and the HUD shows the
29	 * confirmed one. `window.__duel` exposes read-only diagnostics for tests. `dispose` stops it (a duel at sea ends).
30	 */
31	export class DuelClient implements ArenaSource {
32	  private session: DuelClientSession | undefined;
33	  private status: DuelConnectionStatus = "connected";
34	  private boxes = false;
35	  private readonly keyboard: DuelKeyboard;
36	  private readonly timers: number[] = [];
37	  private readonly unsubscribe: (() => void)[] = [];
38	  private readonly pendingEvents = new PendingDuelEvents();
39	
40	  constructor(
41	    private readonly transport: DuelTransport,
42	    private readonly hud: HTMLElement,
43	  ) {
44	    this.keyboard = new DuelKeyboard(window);
45	    this.unsubscribe.push(
46	      transport.onMessage(DuelMessageType.Probe, (message: unknown) => {
47	        const probe = duelProbeSchema.safeParse(message);
48	        if (!probe.success) return;
49	        transport.send(DuelMessageType.Probe, { id: probe.data.id } satisfies DuelProbeReply);
50	        this.ensureSession()?.receiveProbe(probe.data, performance.now());
51	      }),
52	      transport.onMessage(DuelMessageType.Frames, (message: unknown) => {
53	        const bundle = duelFrameBundleSchema.safeParse(message);
54	        if (bundle.success) this.ensureSession()?.receiveBundle(bundle.data, performance.now());
55	      }),
56	      transport.onDrop(() => {
57	        this.status = "reconnecting";
58	      }),
59	      transport.onReconnect(() => {
60	        this.status = "connected";
61	      }),
62	      transport.onLeave(() => {
63	        this.status = "disconnected";
64	        this.renderHud();
65	        this.stopTimers();
66	      }),
67	    );
68	    this.timers.push(window.setInterval(() => this.tick(), TICK_MS));
69	    this.timers.push(window.setInterval(() => this.renderHud(), HUD_MS));
70	    (window as unknown as { __duel: unknown }).__duel = {
71	      stats: () => this.session?.stats,
72	      frame: () => this.session?.frame,
73	      confirmedFrame: () => this.session?.rollback.confirmedFrame,
74	      lastTaggedFrame: () => this.session?.lastTaggedFrame,
75	      /** The input bits this client tagged for frames `from` to `to` (0 where none was). */
76	      taggedInputs: (from: number, to: number) =>
77	        Array.from({ length: Math.max(0, to - from + 1) }, (_, index) => this.session?.rollback.localInput(from + index) ?? 0),
78	    };
79	  }
80	
81	  /** The developer toggle for hurtboxes and hitboxes. */
82	  setShowBoxes(show: boolean): void {
83	    this.boxes = show;
84	  }
85	
86	  /** Practice rooms: the dummy idles or guards. */
87	  setDummy(dummy: DummyBehaviour): void {
88	    this.transport.send(DuelMessageType.Practice, { dummy } satisfies DuelPracticeMessage);
89	  }
90	
91	  /** The arena is up: at sea the fight waits for both fighters to say so (§6). */
92	  ready(): void {
93	    this.transport.ready();
94	  }
95	
96	  /** Stops the timers, the keyboard and the subscriptions: this duel is over and its view is gone. */
97	  dispose(): void {
98	    this.stopTimers();
99	    this.keyboard.dispose();
100	    for (const unsubscribe of this.unsubscribe.splice(0)) unsubscribe();
101	  }
102	
103	  state(): DuelState | undefined {
104	    return this.session?.state;
105	  }
106	
107	  drainEvents(): DuelFeedEvent[] {
108	    this.collectEvents();
109	    return this.pendingEvents.drain();
110	  }
111	
112	  stateAt(frame: number): DuelState | undefined {
113	    return this.session?.rollback.stateAt(frame);
114	  }
115	
116	  showBoxes(): boolean {
117	    return this.boxes;
118	  }
119	
120	  banner(): string {
121	    const lobby = this.transport.lobby();
122	    if (lobby === undefined) return "";
123	    if (lobby.phase === "waiting") return lobby.practice ? "" : "Waiting for an opponent";
124	    if (lobby.phase === "countdown") return String(Math.max(1, Math.ceil(lobby.countdown / 60)));
125	    if (lobby.phase === "over") return resultText(lobby.winner, lobby.reason);
126	    return (this.session?.frame ?? 0) < 45 ? "FIGHT" : "";
127	  }
128	
129	  private get self(): PlayerIndex | undefined {
130	    const seats = this.transport.lobby()?.seats;
131	    const seat = seats === undefined ? undefined : [...seats].find((entry) => entry.sessionId === this.transport.sessionId);
132	    return seat === undefined ? undefined : (seat.slot as PlayerIndex);
133	  }
134	
135	  /**
136	   * The session, created once the lobby is known. At sea it is dropped while the duel waits for a fighter who is still
137	   * loading after the countdown, so the fight's clock starts from the fight's own frames, not from a paused countdown.
138	   */
139	  private ensureSession(): DuelClientSession | undefined {
140	    const lobby = this.transport.lobby();
141	    if (lobby?.phase === "waiting") this.session = undefined;
142	    if (this.session !== undefined) return this.session;
143	    const self = this.self;
144	    if (lobby === undefined || lobby.phase === "waiting" || self === undefined) return undefined;
145	    this.session = new DuelClientSession({ config: defaultDuelConfig, player: self, initial: createDuelState(defaultDuelConfig, { seed: lobby.seed }) });
146	    return this.session;
147	  }
148	
149	  private tick(): void {
150	    const session = this.ensureSession();
151	    if (session === undefined) return;
152	    // Once the result is in, nothing the player presses matters any more, but the final bundle is still stepped, so
153	    // the HUD's health, clock and result end on the server's last frame.
154	    const lobby = this.transport.lobby();
155	    if (lobby?.phase === "over") {
156	      session.finish();
157	      this.collectEvents();
158	      return;
159	    }
160	    const delay = lobby?.inputDelay ?? 0;
161	    if (delay > 0) session.inputDelay = delay;
162	    const tagged = session.lastTaggedFrame;
163	    const message = session.tick(performance.now(), this.keyboard.bits());
164	    if (session.lastTaggedFrame > tagged) this.keyboard.framesTagged();
165	    if (message !== undefined) this.transport.send(DuelMessageType.Input, message);
166	    this.collectEvents();
167	  }
168	
169	  /** Events are drained every tick, so none is lost while the arena is not drawing (a hidden tab). */
170	  private collectEvents(): void {
171	    this.pendingEvents.collect(this.session?.drainEvents() ?? []);
172	  }
173	
174	  private stopTimers(): void {
175	    for (const timer of this.timers.splice(0)) window.clearInterval(timer);
176	  }
177	
178	  private renderHud(): void {
179	    const lobby: DuelLobby | undefined = this.transport.lobby();
180	    const self = this.self;
181	    if (lobby === undefined || self === undefined) return;
182	    const session = this.session;
183	    const seats = [...lobby.seats];
184	    const connected = [0, 1].map((slot) => seats.find((seat) => seat.slot === slot)?.connected ?? false) as [boolean, boolean];
185	    renderDuelHud(this.hud, {
186	      code: lobby.code,
187	      practice: lobby.practice,
188	      phase: lobby.phase as DuelRoomPhase,
189	      status: this.status,
190	      self,
191	      countdown: lobby.countdown,
192	      connected,
193	      confirmed: session?.confirmedState ?? createDuelState(defaultDuelConfig, { seed: lobby.seed }),
194	      maxHealth: rules.maxHealth,
195	      maxStamina: rules.maxStamina,
196	      roundFrames: rules.roundFrames,
197	      overtimeFrames: rules.overtimeFrames,
198	      rttMs: session?.rttMs ?? 0,
199	      inputDelay: lobby.inputDelay,
200	      corrections: session?.stats.corrections ?? 0,
201	      result: lobby.phase === "over" ? { winner: lobby.winner, reason: lobby.reason } : undefined,
202	    });
203	  }
204	}
