1	import * as Phaser from "phaser";
2	import { HEADING_COUNT, insideIsland, ISLAND_THEMES, SIGHT_RADIUS_TILES, Terrain, terrainAt } from "@pirate-sea-race/content";
3	import { encounterRules } from "@pirate-sea-race/content/encounters";
4	import { defaultSimulationConfig } from "@pirate-sea-race/simulation";
5	import { ArenaScene, type ArenaSource } from "./arenaScene.js";
6	import { followScroll, TILE_PIXELS, VIEW_HEIGHT, VIEW_WIDTH } from "./camera.js";
7	import { FogOfWar } from "./fog.js";
8	import { elapsedText } from "./hud.js";
9	import { cssColor, slotColor, type MatchView } from "./matchView.js";
10	import {
11	  AIM_COLOR,
12	  DOCK_COLOR,
13	  DOCK_PLANK,
14	  FOG_COLOR,
15	  GRID_COLOR,
16	  INCOMING_COLOR,
17	  LAND_COLORS,
18	  MARKER_COLOR,
19	  OWN_RING_COLOR,
20	  PROTECTION_COLOR,
21	  SEA_COLOR,
22	  SHOAL_COLOR,
23	  SHOAL_FLECK,
24	  SIGHT_COLOR,
25	  TELEGRAPH_COLOR,
26	} from "./palette.js";
27	
28	const { map } = defaultSimulationConfig;
29	const WORLD_WIDTH = map.widthTiles * TILE_PIXELS;
30	const WORLD_HEIGHT = map.heightTiles * TILE_PIXELS;
31	const PIXELS_PER_SUB_UNIT = TILE_PIXELS / map.subUnitsPerTile;
32	/** The placeholder art was drawn for 16 px tiles; its details scale with the tile. */
33	const ART_SCALE = TILE_PIXELS / 16;
34	
35	/** Tile indexes in the generated tileset texture. */
36	const TILE_SEA = 0;
37	const TILE_SHOAL = 1;
38	const TILE_DOCK = 2;
39	const TILE_LAND = 3;
40	
41	const MINIMAP_SCALE = 1.25;
42	const MINIMAP_MARGIN = 8;
43	
44	/** A grapple's reach and hit area as drawn: the range, and ±hit cone headings either side of the aim. */
45	const GRAPPLE_RANGE_PIXELS = encounterRules.grapple.rangeTiles * TILE_PIXELS;
46	const GRAPPLE_HALF_ANGLE = (encounterRules.grapple.hitConeHeadings * 2 * Math.PI) / HEADING_COUNT;
47	
48	/** A telegraph as drawn this frame, for the DOM report tests read: whose, at whom, and from whose side. */
49	export interface DrawnTelegraph {
50	  readonly attackerId: string;
51	  readonly defenderId: string;
52	  readonly aim: number;
53	  /** "own" (this player's aim), "incoming" (aimed at this player) or "other". */
54	  readonly role: "own" | "incoming" | "other";
55	}
56	
57	/** A duel marker as drawn this frame, in canvas pixels, with the elapsed time it shows. */
58	export interface DrawnMarker {
59	  readonly x: number;
60	  readonly y: number;
61	  readonly elapsed: string;
62	}
63	
64	
65	/** A ship as drawn this frame, in canvas pixels, for the DOM report tests read. */
66	export interface DrawnShip {
67	  readonly id: string;
68	  readonly x: number;
69	  readonly y: number;
70	  readonly color: string;
71	}
72	
73	function landTile(tileX: number, tileY: number): number {
74	  const theme = map.islands.find((island) => insideIsland(island, tileX, tileY))?.theme ?? "tropical";
75	  return TILE_LAND + ISLAND_THEMES.indexOf(theme);
76	}
77	
78	function tileIndex(tileX: number, tileY: number): number {
79	  switch (terrainAt(map, tileX, tileY)) {
80	    case Terrain.Land:
81	      return landTile(tileX, tileY);
82	    case Terrain.Shoal:
83	      return TILE_SHOAL;
84	    case Terrain.Dock:
85	      return TILE_DOCK;
86	    default:
87	      return TILE_SEA;
88	  }
89	}
90	
91	function tileColor(tileX: number, tileY: number): number {
92	  const index = tileIndex(tileX, tileY);
93	  if (index >= TILE_LAND) return LAND_COLORS[ISLAND_THEMES[index - TILE_LAND]!];
94	  return [SEA_COLOR, SHOAL_COLOR, DOCK_COLOR][index]!;
95	}
96	
97	/**
98	 * Draws the sea: the tile map from content, the ships the server sent at interpolated positions, a camera that
99	 * follows the player's ship, the sight circle, and a minimap whose fog clears along the player's path. The encounters
100	 * of §6 are drawn over it: each grapple's telegraph (its reach and hit area along the locked aim, filling in as the
101	 * windup runs out; the player's own in green, one aimed at the player in red with a warning arrow on its ship, others
102	 * in sand), a duel marker (crossed swords and the elapsed time) where a duel runs, and a ring round the player's ship
103	 * while it is protected. Each frame it records what it drew in data attributes on the report element
104	 * (`data-drawn-ships`, `data-telegraphs`, `data-markers`, `data-camera`, `data-fog-revealed`, and once
105	 * `data-minimap`: the minimap's left, top and scale on the canvas) for the browser tests.
106	 */
107	export class SeaScene extends Phaser.Scene {
108	  private readonly shipGraphics = new Map<string, Phaser.GameObjects.Graphics>();
109	  private encounterGraphics!: Phaser.GameObjects.Graphics;
110	  private readonly markerLabels: Phaser.GameObjects.Text[] = [];
111	  private lastEncounterReport = "";
112	  private readonly fog = new FogOfWar(map.widthTiles, map.heightTiles, SIGHT_RADIUS_TILES);
113	  private minimap!: Phaser.Textures.CanvasTexture;
114	  private minimapMarks!: Phaser.GameObjects.Graphics;
115	  private sight!: Phaser.GameObjects.Graphics;
116	  private lastReport = "";
117	
118	  constructor(
119	    private readonly view: MatchView,
120	    private readonly report: HTMLElement,
121	  ) {
122	    super("sea");
123	  }
124	
125	  create(): void {
126	    this.createTerrain();
127	    this.sight = this.add.graphics();
128	    this.sight.lineStyle(1, SIGHT_COLOR, 0.45);
129	    this.sight.strokeCircle(0, 0, SIGHT_RADIUS_TILES * TILE_PIXELS);
130	    this.sight.setDepth(1);
131	    this.encounterGraphics = this.add.graphics().setDepth(1.5);
132	    this.createMinimap();
133	  }
134	
135	  /** The tile map, as a Phaser tilemap over a tileset texture drawn here in placeholder colours. */
136	  private createTerrain(): void {
137	    const kinds = TILE_LAND + ISLAND_THEMES.length;
138	    const tileset = this.textures.createCanvas("terrain-tiles", kinds * TILE_PIXELS, TILE_PIXELS)!;
139	    const context = tileset.getContext();
140	    const paint = (index: number, color: number) => {
141	      context.fillStyle = cssColor(color);
142	      context.fillRect(index * TILE_PIXELS, 0, TILE_PIXELS, TILE_PIXELS);
143	    };
144	    paint(TILE_SEA, SEA_COLOR);
145	    paint(TILE_SHOAL, SHOAL_COLOR);
146	    context.fillStyle = cssColor(SHOAL_FLECK);
147	    for (const [x, y] of [[3, 4], [10, 2], [6, 10], [13, 12], [2, 13]] as const) {
148	      context.fillRect(TILE_SHOAL * TILE_PIXELS + Math.round(x * ART_SCALE), Math.round(y * ART_SCALE), 2 * ART_SCALE, 2 * ART_SCALE);
149	    }
150	    paint(TILE_DOCK, DOCK_COLOR);
151	    context.fillStyle = cssColor(DOCK_PLANK);
152	    for (const y of [4, 9, 14]) context.fillRect(TILE_DOCK * TILE_PIXELS, Math.round(y * ART_SCALE), TILE_PIXELS, 1);
153	    ISLAND_THEMES.forEach((theme, index) => paint(TILE_LAND + index, LAND_COLORS[theme]));
154	    tileset.refresh();
155	
156	    // Open sea is left empty (-1): the camera's background is the sea, so the layer draws only the few land, shoal
157	    // and dock tiles in view. Drawing every sea tile too costs a software renderer most of its frame rate.
158	    const data = Array.from({ length: map.heightTiles }, (_, tileY) =>
159	      Array.from({ length: map.widthTiles }, (_, tileX) => {
160	        const index = tileIndex(tileX, tileY);
161	        return index === TILE_SEA ? -1 : index;
162	      }),
163	    );
164	    const tilemap = this.make.tilemap({ data, tileWidth: TILE_PIXELS, tileHeight: TILE_PIXELS });
165	    const tiles = tilemap.addTilesetImage("terrain", "terrain-tiles", TILE_PIXELS, TILE_PIXELS, 0, 0)!;
166	    tilemap.createLayer(0, tiles, 0, 0);
167	
168	    // A chart grid every eight tiles, so open water shows the ship's motion.
169	    const grid = this.add.graphics();
170	    grid.lineStyle(1, GRID_COLOR, 0.6);
171	    for (let tile = 0; tile <= map.widthTiles; tile += 8) grid.lineBetween(tile * TILE_PIXELS, 0, tile * TILE_PIXELS, WORLD_HEIGHT);
172	    for (let tile = 0; tile <= map.heightTiles; tile += 8) grid.lineBetween(0, tile * TILE_PIXELS, WORLD_WIDTH, tile * TILE_PIXELS);
173	
174	    for (const island of map.islands) {
175	      const label = this.add.text((island.tileX + island.widthTiles / 2) * TILE_PIXELS, (island.tileY - 1.2) * TILE_PIXELS, island.name, {
176	        fontFamily: "system-ui, sans-serif",
177	        fontSize: `${12 * ART_SCALE}px`,
178	        color: "#e8f1f5",
179	      });
180	      label.setOrigin(0.5, 0.5).setAlpha(0.85);
181	    }
182	  }
183	
184	  /** The minimap: one pixel per tile, fogged until the player's ship has seen it. */
185	  private createMinimap(): void {
186	    this.minimap = this.textures.createCanvas("minimap", map.widthTiles, map.heightTiles)!;
187	    const context = this.minimap.getContext();
188	    context.fillStyle = cssColor(FOG_COLOR);
189	    context.fillRect(0, 0, map.widthTiles, map.heightTiles);
190	    this.minimap.refresh();
191	    const left = VIEW_WIDTH - MINIMAP_MARGIN - map.widthTiles * MINIMAP_SCALE;
192	    const frame = this.add.graphics().setScrollFactor(0).setDepth(10);
193	    frame.lineStyle(2, 0x9bb8c6, 0.9);
194	    frame.strokeRect(left - 1, MINIMAP_MARGIN - 1, map.widthTiles * MINIMAP_SCALE + 2, map.heightTiles * MINIMAP_SCALE + 2);
195	    this.add.image(left, MINIMAP_MARGIN, "minimap").setOrigin(0, 0).setScale(MINIMAP_SCALE).setScrollFactor(0).setDepth(10);
196	    this.minimapMarks = this.add.graphics().setScrollFactor(0).setDepth(11);
197	    this.report.dataset["minimap"] = `${left},${MINIMAP_MARGIN},${MINIMAP_SCALE}`;
198	  }
199	
200	  private revealFog(x: number, y: number): void {
201	    const fresh = this.fog.revealAround(Math.floor(x / TILE_PIXELS), Math.floor(y / TILE_PIXELS));
202	    if (fresh.length === 0) return;
203	    const context = this.minimap.getContext();
204	    for (const [tileX, tileY] of fresh) {
205	      context.fillStyle = cssColor(tileColor(tileX, tileY));
206	      context.fillRect(tileX, tileY, 1, 1);
207	    }
208	    this.minimap.refresh();
209	    this.report.dataset["fogRevealed"] = String(this.fog.revealedCount);
210	  }
211	
212	  override update(): void {
213	    const now = performance.now();
214	    const own = this.view.renderPosition(this.view.selfId, now);
215	    if (own !== undefined) {
216	      const x = own.x * PIXELS_PER_SUB_UNIT;
217	      const y = own.y * PIXELS_PER_SUB_UNIT;
218	      const scroll = followScroll(x, y);
219	      this.cameras.main.setScroll(scroll.x, scroll.y);
220	      this.sight.setPosition(x, y);
221	      this.revealFog(x, y);
222	    }
223	    const camera = this.cameras.main;
224	    const minimapLeft = VIEW_WIDTH - MINIMAP_MARGIN - map.widthTiles * MINIMAP_SCALE;
225	    this.minimapMarks.clear();
226	
227	    const drawn: DrawnShip[] = [];
228	    const present = new Set<string>();
229	    for (const ship of this.view.ships()) {
230	      const position = this.view.renderPosition(ship.id, now);
231	      if (position === undefined) continue;
232	      present.add(ship.id);
233	      const mine = ship.id === this.view.selfId;
234	      let graphics = this.shipGraphics.get(ship.id);
235	      if (graphics === undefined) {
236	        graphics = this.drawShip(slotColor(ship.slot), mine);
237	        this.shipGraphics.set(ship.id, graphics);
238	      }
239	      const x = position.x * PIXELS_PER_SUB_UNIT;
240	      const y = position.y * PIXELS_PER_SUB_UNIT;
241	      graphics.setPosition(x, y);
242	      graphics.setRotation((ship.heading * 2 * Math.PI) / HEADING_COUNT);
243	      drawn.push({ id: ship.id, x: Math.round(x - camera.scrollX), y: Math.round(y - camera.scrollY), color: cssColor(slotColor(ship.slot)) });
244	      this.minimapMarks.fillStyle(mine ? OWN_RING_COLOR : slotColor(ship.slot), 1);
245	      this.minimapMarks.fillRect(minimapLeft + (x / TILE_PIXELS) * MINIMAP_SCALE - 1.5, MINIMAP_MARGIN + (y / TILE_PIXELS) * MINIMAP_SCALE - 1.5, 3, 3);
246	    }
247	    for (const [id, graphics] of this.shipGraphics) {
248	      if (present.has(id)) continue;
249	      graphics.destroy();
250	      this.shipGraphics.delete(id);
251	    }
252	    const report = JSON.stringify(drawn);
253	    if (report !== this.lastReport) {
254	      this.report.dataset["drawnShips"] = report;
255	      this.lastReport = report;
256	    }
257	    this.drawEncounters(now);
258	    this.report.dataset["camera"] = `${camera.scrollX},${camera.scrollY}`;
259	  }
260	
261	  /** Telegraphs, duel markers and the player's protection ring (§6), under the ships. */
262	  private drawEncounters(now: number): void {
263	    const graphics = this.encounterGraphics;
264	    graphics.clear();
265	    const camera = this.cameras.main;
266	    const tick = this.view.worldTick();
267	    const pixels = (position: { x: number; y: number }) => ({ x: position.x * PIXELS_PER_SUB_UNIT, y: position.y * PIXELS_PER_SUB_UNIT });
268	
269	    const telegraphs: DrawnTelegraph[] = [];
270	    for (const grapple of this.view.grapples()) {
271	      const role = grapple.attackerId === this.view.selfId ? "own" : grapple.defenderId === this.view.selfId ? "incoming" : "other";
272	      telegraphs.push({ attackerId: grapple.attackerId, defenderId: grapple.defenderId, aim: grapple.aim, role });
273	      const from = this.view.renderPosition(grapple.attackerId, now);
274	      if (from === undefined) continue;
275	      const { x, y } = pixels(from);
276	      const color = role === "own" ? AIM_COLOR : role === "incoming" ? INCOMING_COLOR : TELEGRAPH_COLOR;
277	      const angle = (grapple.aim * 2 * Math.PI) / HEADING_COUNT;
278	      const progress = Math.min(1, Math.max(0, (tick - grapple.startTick) / Math.max(1, grapple.landTick - grapple.startTick)));
279	      // The hit area: a wedge whose fill deepens as the windup runs out, and the aim line down its middle.
280	      graphics.fillStyle(color, 0.12 + 0.3 * progress);
281	      graphics.slice(x, y, GRAPPLE_RANGE_PIXELS, angle - GRAPPLE_HALF_ANGLE, angle + GRAPPLE_HALF_ANGLE, false);
282	      graphics.fillPath();
283	      graphics.lineStyle(2, color, 0.9);
